package main

import (
	"fmt"
	"io"
	"os"
)

func logLine(text string) error {
	f, err := os.OpenFile("visits.log", os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o644)
	if err != nil {
		return err
	}
	defer f.Close()
	_, err = fmt.Fprintln(f, text)
	return err
}

func main() {
	os.WriteFile("visits.log", nil, 0o644) // start each run with an empty log

	logLine("09:00 Ana collected parcel 7")
	logLine("09:30 Bo dropped off parcel 9")

	f, err := os.Open("visits.log")
	if err != nil {
		fmt.Println(err)
		return
	}
	defer f.Close()
	all, err := io.ReadAll(f)
	fmt.Printf("%d bytes, err=%v\n%s", len(all), err, all)
}

