package main

import (
	"fmt"
	"os"
)

func openFiles() int {
	fds, _ := os.ReadDir("/proc/self/fd") // Linux: one entry per open file
	return len(fds)
}

func check(name string) error {
	f, err := os.Open(name)
	if err != nil {
		return err
	}
	defer f.Close() // runs when check returns: once per file
	fmt.Println(name, "open files:", openFiles())
	return nil
}

func main() {
	names := []string{"parcels.txt", "banner.txt", "archive/readme.txt", "letters/ana.txt"}
	for _, name := range names {
		if err := check(name); err != nil {
			fmt.Println(err)
			return
		}
	}
}

