// Package stamps prints postage marks in colour. This is version 2.
package stamps

// Color is an ink colour.
type Color string

// The colours a stamp can be.
const (
	Red  Color = "red"
	Blue Color = "blue"
)

// Stamp returns the label with a coloured postage mark in front.
// Version 2 needs the colour: calls written for v1 no longer compile.
func Stamp(label string, c Color) string {
	return "[STAMPED in " + string(c) + "] " + label
}

