package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	// 1. Create a file (or empty it if it exists) and write to it.
	f, err := os.Create("notes.txt")
	if err != nil {
		fmt.Println("create failed:", err)
		return
	}
	fmt.Fprintln(f, "pick up parcel 7")
	fmt.Fprintln(f, "deliver parcel 8")
	f.Close()

	// 2. Open it again and read it line by line.
	r, err := os.Open("notes.txt")
	if err != nil {
		fmt.Println("open failed:", err)
		return
	}
	defer r.Close()

	sc := bufio.NewScanner(r)
	n := 0
	for sc.Scan() {
		n++
		fmt.Printf("line %d: %s\n", n, sc.Text())
	}
	if err := sc.Err(); err != nil {
		fmt.Println("read failed:", err)
	}
}
